%% clau ASN.1 modules compiled for PER (aligned) against asn1ct: the encodings, decodings and error reasons of the
%% Kitchen and PerKitchen types (plan 21 step LIB84).
-module(asn1_per).
-export([main/1]).
-include("Kitchen.hrl").
-include("PerKitchen.hrl").

main(_) ->
    [roundtrip('Kitchen', T, V) || {T, V} <- kitchen_values()],
    [decode_only('Kitchen', T, B) || {T, B} <- kitchen_encodings()],
    [roundtrip('PerKitchen', T, V) || {T, V} <- per_values()],
    [decode_only('PerKitchen', T, B) || {T, B} <- per_encodings()],
    io:format("asn1_per: ok~n").

roundtrip(Module, Type, Value) ->
    case Module:encode(Type, Value) of
        {ok, Bin} ->
            io:format("~p ~W~n  => ~W~n  <= ~W~n", [
                Type, Value, 30, Bin, 40, decode(Module, Type, Bin), 30
            ]);
        {error, {asn1, {Reason, _}}} ->
            io:format("~p ~W~n  => error ~W~n", [Type, Value, 30, Reason, 30])
    end.

decode_only(Module, Type, Bin) ->
    io:format("~p ~w~n  <= ~W~n", [Type, Bin, decode(Module, Type, Bin), 30]).

decode(Module, Type, Bin) ->
    case Module:decode(Type, Bin) of
        {ok, V} -> V;
        {error, {asn1, {R, _}}} -> {error, R}
    end.

